node prog "The game's memory"
link hex slot {s} #0100 "Its program, from #0100"
link hex slot {s} #9486 "Its variables, from var_first"
link hex slot {s} #BF00 "The page table (#BF00: a NEX data page -> the archive's)"
link hex slot {s} #F680 "The console's state (#F680: its strip [n] at #F68A)"
link text slot {s} #F700 "Its console's text"

node program "The program, from #0100"
src slot {s} #0100 2048
view hex

node console "Its console's text (#F700)"
src slot {s} #F700 2000
view text

node pages "The page table (#BF00)"
src slot {s} #BF00 128
rec 2
count 64
f "NEX bank" #
f "Page" b 0
f "Page" b 1
view list

node hex k p a "Memory in hex"
title "Hex: {1} {2} {3}"
src {1} {2} {3}
view hex

node text k p a "Memory as text"
title "Text: {1} {2} {3}"
src {1} {2} {3}
view text
